1	/**
2	 * LanChat 前端交互逻辑。
3	 *
4	 * 全局状态:
5	 *   myInfo       - 本机信息 {uuid, name, ip, network, ws_port}
6	 *   onlinePeers  - 在线节点 Map<uuid, {name, ip}>
7	 *   contacts     - 历史联系人 Map<uuid, {name, ip, status, messages[]}>
8	 *   pendingReqs  - 待处理连接请求 Map<uuid, {name}>
9	 *   activeChats  - 活跃聊天 WS Map<uuid, WebSocket>
10	 *   currentChat  - 当前显示的聊天 uuid | null
11	 *   pendingMsgs  - 待确认消息 Map<msg_id, {content, uuid, timestamp}>
12	 *   pendingFileTransfers - 待处理的文件上传 {transferId: {file, uuid, ...}}
13	 */
14	
15	// ===== 全局状态 =====
16	let myInfo = null;
17	let onlinePeers = new Map();
18	let contacts = new Map();
19	let pendingRequests = new Map();
20	let activeChats = new Map();         // uuid → WebSocket（主动发起方有值）
21	let connectedPeers = new Set();      // 连接已确认的 peer uuid（双方向都追踪，含接收方）
22	let currentChat = null;
23	let pendingMessages = new Map();
24	let controlWs = null;
25	let reconnectTimer = null;
26	let reconnectAttempts = 0;
27	
28	// ===== sessionStorage：刷新后记住连接状态 =====
29	const SS_PREFIX = 'lanchat_conn_';
30	
31	function markConnected(uuid) {
32	    try { sessionStorage.setItem(SS_PREFIX + uuid, '1'); } catch (e) { /* ignore */ }
33	}
34	
35	function markDisconnected(uuid) {
36	    try { sessionStorage.removeItem(SS_PREFIX + uuid); } catch (e) { /* ignore */ }
37	}
38	
39	function getStoredConnectedPeers() {
40	    const peers = [];
41	    try {
42	        for (let i = 0; i < sessionStorage.length; i++) {
43	            const key = sessionStorage.key(i);
44	            if (key && key.startsWith(SS_PREFIX)) {
45	                peers.push(key.slice(SS_PREFIX.length));
46	            }
47	        }
48	    } catch (e) { /* ignore */ }
49	    return peers;
50	}
51	
52	// 文件传输状态
53	let pendingFileTransfers = {};
54	
55	// ===== DOM 引用 =====
56	const $ = (id) => document.getElementById(id);
57	const onlineList = $('online-list');
58	const onlineCount = $('online-count');
59	const pendingList = $('pending-list');
60	const pendingCount = $('pending-count');
61	const panelPending = $('panel-pending');
62	const contactsList = $('contacts-list');
63	const contactsCount = $('contacts-count');
64	const chatPlaceholder = $('chat-placeholder');
65	const chatContainer = $('chat-container');
66	const chatPeerName = $('chat-peer-name');
67	const chatPeerStatus = $('chat-peer-status');
68	const chatConnectBar = $('chat-connect-bar');
69	const btnChatConnect = $('btn-chat-connect');
