94	/** 连接控制 WebSocket */
95	async function connectControl() {
96	    const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
97	    const url = `${protocol}//${location.host}/ws/control`;
98	
99	    return new Promise((resolve) => {
100	        controlWs = new WebSocket(url);
101	
102	        controlWs.onopen = () => {
103	            reconnectAttempts = 0;
104	            console.log('[Control] 已连接');
105	        };
106	
107	        controlWs.onmessage = (e) => {
108	            const msg = JSON.parse(e.data);
109	            handleControlMessage(msg);
110	            if (msg.type === 'init') resolve();
111	        };
112	
113	        controlWs.onclose = () => {
114	            console.log('[Control] 断开，尝试重连...');
115	            scheduleReconnect();
116	        };
117	
118	        controlWs.onerror = () => {};
119	    });
120	}
