122	/** 控制 WS 断开后指数退避重连 */
123	function scheduleReconnect() {
124	    if (reconnectTimer) return;
125	    const delay = Math.min(1000 * Math.pow(2, reconnectAttempts), 30000);
126	    const jitter = delay * (0.8 + Math.random() * 0.4);
127	    reconnectAttempts++;
128	    reconnectTimer = setTimeout(async () => {
129	        reconnectTimer = null;
130	        await connectControl();
131	    }, jitter);
132	}
