220	// ===== 控制消息处理 =====
221	function handleControlMessage(msg) {
222	    const handlers = {
223	        init: handleInit,
224	        peer_online: handlePeerOnline,
225	        peer_offline: handlePeerOffline,
226	        incoming_connection: handleIncomingConnection,
227	        pending_update: handlePendingUpdate,
228	        connection_established: handleConnectionEstablished,
229	        peer_disconnected: handlePeerDisconnected,
230	        disconnected: handleDisconnected,
231	        contact_deleted: handleContactDeleted,
232	        contact_untrusted: handleContactUntrusted,
233	        connection_timeout: handleConnectionTimeout,
234	        connection_idle_close: handleConnectionIdleClose,
235	        chat_message: handleIncomingMessage,
236	        message_ack: handleMessageAck,
237	        send_failed: handleSendFailed,
238	        incoming_file_request: handleIncomingFileRequest,
239	        file_request_response: handleFileRequestResponseFromControl,
240	        forward_file_response: handleForwardFileResponse,
241	        transfer_progress: handleTransferProgress,
242	        transfer_complete: handleTransferComplete,
243	        transfer_cancelled: handleTransferCancelled,
244	        transfer_resumed: handleTransferResumed,
245	    };
246	    const handler = handlers[msg.type];
247	    if (handler) handler(msg);
248	}
