568	/**
569	 * 统一处理文件请求响应。
570	 * 发送方会从聊天 WS 直连或控制 WS 两条路径收到此消息，
571	 * 通过 transfer_id 精确匹配，且幂等（started 标记防止重复启动上传）。
572	 */
573	function handleFileRequestResponse(msg) {
574	    const transferId = msg.transfer_id;
575	    const t = pendingFileTransfers[transferId];
576	    if (!t) return; // 不是我们的传输
577	
578	    if (msg.accepted) {
579	        if (t.started) return; // 已启动，幂等
580	        t.started = true;
581	        startChunkUpload(transferId);
582	    } else {
583	        // 对方拒绝
584	        delete pendingFileTransfers[transferId];
585	        const result = findFileMsgByTransferId(transferId);
586	        if (result) {
587	            result.msg.status = 'failed';
588	            // 通过 transferId 找到对应的联系人 uuid
589	            saveFileMessage(t.uuid, result.msg);
590	            if (currentChat) renderMessages(currentChat);
591	        }
592	        showToast('对方拒绝了文件传输');
593	    }
594	}
