596	function handleTransferProgress(msg) {
597	    // 接收方：更新文件消息进度
598	    const result = findFileMsgByTransferId(msg.transfer_id);
599	    if (result && msg.total_bytes > 0) {
600	        result.msg.progress = Math.round(msg.received_bytes / msg.total_bytes * 100);
601	        if (currentChat) renderMessages(currentChat);
602	    }
603	}
