605	function handleTransferComplete(msg) {
606	    // 接收方：传输完成
607	    const result = findFileMsgByTransferId(msg.transfer_id);
608	    if (result) {
609	        const { msg: fileMsg, peerUuid } = result;
610	        fileMsg.status = msg.verified ? 'complete' : 'failed';
611	        fileMsg.progress = 100;
612	        saveFileMessage(peerUuid, fileMsg);
613	        if (currentChat === peerUuid) renderMessages(currentChat);
614	    }
615	    if (msg.verified) {
616	        showToast(`文件接收完成: ${msg.file_name}`);
617	    } else {
618	        showToast(`文件校验失败: ${msg.file_name}`);
619	    }
620	}
