622	function handleTransferCancelled(msg) {
623	    const result = findFileMsgByTransferId(msg.transfer_id);
624	    if (result) {
625	        const { msg: fileMsg, peerUuid } = result;
626	        fileMsg.status = 'cancelled';
627	        saveFileMessage(peerUuid, fileMsg);
628	        if (currentChat === peerUuid) renderMessages(currentChat);
629	    }
630	    // 清理上传方状态
631	    if (pendingFileTransfers[msg.transfer_id]) {
632	        delete pendingFileTransfers[msg.transfer_id];
633	    }
634	    showToast('文件传输已取消');
635	}
