637	function handleTransferResumed(msg) {
638	    // 续传恢复通知 — 不做额外弹窗，进度条会在 transfer_progress 中更新
639	    const result = findFileMsgByTransferId(msg.transfer_id);
640	    if (result) {
641	        result.msg.status = 'downloading';
642	        // 持久化状态变更（里程碑切换：failed/cancelled → downloading）
643	        saveFileMessage(result.peerUuid, result.msg);
644	        if (currentChat) renderMessages(currentChat);
645	    }
646	}
