1856	/**
1857	 * 开始分片上传文件到对方后端。
1858	 * 每发送一个分片后更新聊天气泡中的进度。
1859	 */
1860	async function startChunkUpload(transferId) {
1861	    const t = pendingFileTransfers[transferId];
1862	    if (!t) return;
1863	
1864	    const result = findFileMsgByTransferId(transferId);
1865	    const fileMsg = result ? result.msg : null;
1866	    if (result) {
1867	        fileMsg.status = 'uploading';
1868	        saveFileMessage(t.uuid, fileMsg);
1869	        if (currentChat === t.uuid) renderMessages(t.uuid);
1870	    }
1871	
1872	    const peer = onlinePeers.get(t.uuid);
1873	    if (!peer) {
1874	        showToast('对方不在线，无法发送文件');
1875	        if (fileMsg) {
1876	            fileMsg.status = 'failed';
1877	            saveFileMessage(t.uuid, fileMsg);
1878	            if (currentChat === t.uuid) renderMessages(t.uuid);
1879	        }
1880	        delete pendingFileTransfers[transferId];
1881	        return;
1882	    }
1883	
1884	    const file = t.file;
1885	    const CHUNK_SIZE = t.CHUNK_SIZE;
1886	    const totalChunks = t.totalChunks;
1887	    const peerPort = peer.ws_port || 50002;
1888	
1889	    for (let i = t.currentChunk; i < totalChunks; i++) {
1890	        // 检查连接是否被中断（断开连接 / 对方下线）
1891	        if (t.aborted) {
1892	            if (fileMsg) {
1893	                fileMsg.status = 'cancelled';
1894	                saveFileMessage(t.uuid, fileMsg);
1895	                if (currentChat === t.uuid) renderMessages(t.uuid);
1896	            }
1897	            return; // 连接中断，中止上传
1898	        }
1899	
1900	        const start = i * CHUNK_SIZE;
1901	        const end = Math.min(start + CHUNK_SIZE, file.size);
1902	        const blob = file.slice(start, end);
1903	
1904	        let dataB64;
1905	        try {
1906	            dataB64 = await readAsBase64(blob);
1907	        } catch (e) {
1908	            // 文件读取失败（权限变更、文件被删、磁盘错误等），不可恢复
1909	            t.failed = true;
1910	            if (fileMsg) {
1911	                fileMsg.status = 'failed';
1912	                saveFileMessage(t.uuid, fileMsg);
1913	                if (currentChat === t.uuid) renderMessages(t.uuid);
1914	            }
1915	            return;
1916	        }
1917	
1918	        let retries = 0;
1919	        let success = false;
1920	
1921	        while (retries < 3 && !success) {
1922	            try {
1923	                const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
1924	                    method: 'POST',
1925	                    headers: { 'Content-Type': 'application/json' },
1926	                    body: JSON.stringify({
1927	                        transfer_id: transferId,
1928	                        chunk_index: i,
1929	                        data: dataB64,
1930	                    }),
1931	                });
1932	                if (resp.ok) {
1933	                    success = true;
1934	                    t.currentChunk = i + 1;
1935	                    // 更新进度条
1936	                    if (fileMsg) {
1937	                        fileMsg.progress = Math.round((i + 1) / totalChunks * 100);
1938	                        if (currentChat === t.uuid) renderMessages(t.uuid);
1939	                    }
1940	                } else {
1941	                    retries++;
1942	                }
1943	            } catch (e) {
1944	                retries++;
1945	            }
1946	        }
1947	
1948	        if (!success) {
1949	            t.failed = true;
1950	            if (fileMsg) {
1951	                fileMsg.status = 'failed';
1952	                saveFileMessage(t.uuid, fileMsg);
1953	                if (currentChat === t.uuid) renderMessages(t.uuid);
1954	            }
1955	            return; // 传输中断（保留 t 以便续传）
1956	        }
1957	    }
1958	
1959	    // 所有分片发送完毕 → 通知对方合并
1960	    try {
1961	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
1962	            method: 'POST',
1963	            headers: { 'Content-Type': 'application/json' },
1964	            body: JSON.stringify({ transfer_id: transferId }),
1965	        });
1966	        if (fileMsg) {
1967	            fileMsg.status = 'complete';
1968	            fileMsg.progress = 100;
1969	            saveFileMessage(t.uuid, fileMsg);
1970	            if (currentChat === t.uuid) renderMessages(t.uuid);
1971	        }
1972	    } catch (e) {
1973	        if (fileMsg) {
1974	            fileMsg.status = 'failed';
1975	            saveFileMessage(t.uuid, fileMsg);
1976	            if (currentChat === t.uuid) renderMessages(t.uuid);
1977	        }
1978	    }
1979	
1980	    delete pendingFileTransfers[transferId];
1981	}
