1983	/**
1984	 * 重新发送（续传）失败的文件。查询接收方已收分片，只补发缺失部分。
1985	 * @param {string} transferId - 原传输 ID
1986	 */
1987	async function retryFileTransfer(transferId) {
1988	    // 1. 检查是否有文件数据（页面刷新后 File 对象会丢失）
1989	    const t = pendingFileTransfers[transferId];
1990	    if (!t || !t.file) {
