1999	        return;
2000	    }
2001	
2002	    // 2.5 必须有已建立的 chat WS 连接才能续传（否则 file_request 无法送达）
2003	    const chatWs = activeChats.get(t.uuid);
2004	    const isConnected = (chatWs && chatWs.readyState === WebSocket.OPEN) || connectedPeers.has(t.uuid);
2005	    if (!isConnected) {
2006	        showCenterToast('连接按钮都懒得点，那就别想重传文件~');
2007	        return;
2008	    }
2009	
2010	    // 3. 查询接收方已收到的分片数
2011	    let receivedChunks = 0;
2012	    const peerPort = peer.ws_port || 50002;
2013	    try {
2014	        const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/status/${transferId}`);
2015	        if (resp.ok) {
2016	            const status = await resp.json();
2017	            receivedChunks = status.received_chunks_count || 0;
2018	        }
2019	    } catch (e) {
2020	        // 进度丢失，从头开始
2021	        console.log('[Retry] 无法获取进度，从头开始:', e.message);
2022	    }
2023	
2024	    // 4. 更新传输状态 — 从已收到的下一片开始
2025	    t.currentChunk = receivedChunks;
2026	    t.started = false;
2027	    t.failed = false;
2028	    t.aborted = false;
2029	
2030	    // 5. 更新文件消息气泡
2031	    const result = findFileMsgByTransferId(transferId);
2032	    if (result) {
2033	        result.msg.status = 'waiting';
2034	        result.msg.progress = Math.round(receivedChunks / t.totalChunks * 100);
2035	        saveFileMessage(t.uuid, result.msg);
2036	        if (currentChat === t.uuid) renderMessages(t.uuid);
2037	    }
2038	
2039	    // 6. 重新发送 file_request（带 resume 标记，接收方会跳过确认直接接受）
2040	    const fileRequestMsg = {
2041	        transfer_id: transferId,
2042	        file_name: t.file.name,
2043	        file_size: t.file.size,
2044	        chunk_size: t.CHUNK_SIZE,
2045	        total_chunks: t.totalChunks,
2046	        resume: true,
2047	    };
2048	
2049	    const ws = activeChats.get(t.uuid);
2050	    if (ws && ws.readyState === WebSocket.OPEN) {
2051	        ws.send(JSON.stringify({ type: 'file_request', ...fileRequestMsg }));
2052	    } else {
2053	        // 回退路径：通过 control WS 转发
2054	        controlWs.send(JSON.stringify({
2055	            type: 'file_request',
2056	            to_uuid: t.uuid,
2057	            ...fileRequestMsg,
2058	        }));
2059	    }
2060	}
