2062	function readAsBase64(blob) {
2063	    return new Promise((resolve, reject) => {
2064	        const reader = new FileReader();
2065	        reader.onloadend = () => {
2066	            const result = reader.result;
2067	            // 去掉 "data:...;base64," 前缀
2068	            const b64 = result.split(',')[1] || result;
2069	            resolve(b64);
2070	        };
2071	        reader.onerror = () => {
2072	            reject(new Error('文件读取失败'));
2073	        };
2074	        reader.readAsDataURL(blob);
2075	    });
2076	}
